class Solution {
public:
    vector<vector<int>> findMatrix(vector<int>& nums) {
        int n = nums.size();
        vector<int> freq(n + 1, 0);
        int rows = 0;
        for (int x : nums) {
            freq[x]++;
            if (freq[x] > rows) rows = freq[x];
        }
        vector<vector<int>> result(rows);
        vector<int> next(n + 1, 0);
        for (int x : nums) {
            result[next[x]].push_back(x);
            next[x]++;
        }
        return result;
    }
};
